-- ============================================
-- LUMA — Thème 3 : 3e scénario COURT x4 — Négocier une date d'entretien
-- ============================================


update scenarios set content = '{"characters": {"recruiter": "le recruteur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "recruiter", "text": "Hi, I''m calling to schedule your interview. Does Tuesday at 10am work?", "text_fr": "Bonjour, j''appelle pour planifier votre entretien. Mardi à 10h ça vous convient ?", "choices": [{"text": "Tuesday works, but could we do the afternoon instead?", "text_fr": "Mardi ça marche, mais on pourrait faire l''après-midi plutôt ?", "next": "n2"}, {"text": "Unfortunately I have a conflict that day — any other options?", "text_fr": "Malheureusement j''ai un conflit ce jour-là — d''autres options ?", "next": "n2b"}]}, "n2": {"speaker": "recruiter", "text": "Sure, how about 2pm on Tuesday?", "text_fr": "Bien sûr, 14h mardi ça vous va ?", "choices": [{"text": "2pm works perfectly, thank you.", "text_fr": "14h me convient parfaitement, merci.", "next": "n3"}, {"text": "Could we push it to 3pm? I have a prior commitment.", "text_fr": "On pourrait décaler à 15h ? J''ai un engagement précédent.", "next": "n2c"}]}, "n2b": {"speaker": "recruiter", "text": "No problem — how does Wednesday or Thursday sound?", "text_fr": "Aucun problème — mercredi ou jeudi, ça vous dit ?", "choices": [{"text": "Wednesday would be great, any time works for me.", "text_fr": "Mercredi serait super, n''importe quelle heure me va.", "next": "n3"}, {"text": "Thursday morning would be ideal if possible.", "text_fr": "Jeudi matin serait idéal si possible.", "next": "n3"}]}, "n2c": {"speaker": "recruiter", "text": "3pm works too, no problem at all.", "text_fr": "15h ça marche aussi, aucun problème.", "choices": [{"text": "Perfect, thank you for accommodating me.", "text_fr": "Parfait, merci de vous adapter.", "next": "n3"}]}, "n3": {"speaker": "recruiter", "text": "Great, I''ll send a calendar invite with all the details.", "text_fr": "Super, je vous envoie une invitation calendrier avec tous les détails.", "choices": [{"text": "Thank you, will it be in person or virtual?", "text_fr": "Merci, ce sera en personne ou virtuel ?", "next": "n4"}, {"text": "Perfect, I''ll keep an eye out for it.", "text_fr": "Parfait, je vais surveiller ça.", "next": "n4b"}]}, "n4": {"speaker": "recruiter", "text": "It''ll be a video call — I''ll include the link in the invite.", "text_fr": "Ce sera un appel vidéo — j''inclus le lien dans l''invitation.", "choices": [{"text": "Sounds good, thank you for the clarity.", "text_fr": "Ça marche, merci pour la clarté.", "next": "n5"}]}, "n4b": {"speaker": "recruiter", "text": "Sounds good! Do you have any questions before we wrap up?", "text_fr": "Ça marche ! Vous avez des questions avant qu''on termine ?", "choices": [{"text": "Just — how long should I expect the interview to last?", "text_fr": "Juste — combien de temps devrait durer l''entretien ?", "next": "n5"}, {"text": "No, I think I''m all set, thank you.", "text_fr": "Non, je pense être prêt, merci.", "next": "end_confirmed"}]}, "n5": {"speaker": "recruiter", "text": "About 45 minutes, with time for your questions at the end.", "text_fr": "Environ 45 minutes, avec du temps pour vos questions à la fin.", "choices": [{"text": "Perfect, thank you so much for the information.", "text_fr": "Parfait, merci beaucoup pour ces informations.", "next": "end_confirmed"}]}, "end_confirmed": {"speaker": "recruiter", "text": "Great, looking forward to speaking with you then!", "text_fr": "Super, j''ai hâte de vous parler alors !", "end": true, "ending_label": "Entretien planifié avec succès 📅✅"}}}'::jsonb, is_playable = true
where title = 'Négocier une date d''''entretien'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
